def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def amount(tok: str) -> int | None:
        if not tok or any(c < "0" or c > "9" for c in tok):
            return None
        return int(tok)

    for i, op in enumerate(ops):
        t = op.split(" ")
        v = t[0] if t else ""
        ok = False
        if v == "open" and len(t) == 3:
            a, n = t[1], amount(t[2])
            if n is not None and a not in balances:
                balances[a] = n
                history.append(("open", a))
                ok = True
        elif v == "deposit" and len(t) == 3:
            a, n = t[1], amount(t[2])
            if n is not None and n > 0 and a in balances:
                balances[a] += n
                history.append(("deposit", a, n))
                ok = True
        elif v == "withdraw" and len(t) == 3:
            a, n = t[1], amount(t[2])
            if (
                n is not None
                and n > 0
                and a in balances
                and a not in frozen
                and balances[a] >= n
            ):
                balances[a] -= n
                history.append(("withdraw", a, n))
                ok = True
        elif v == "transfer" and len(t) == 4:
            a, b, n = t[1], t[2], amount(t[3])
            if (
                n is not None
                and n > 0
                and a != b
                and a in balances
                and b in balances
                and a not in frozen
                and balances[a] >= n
            ):
                balances[a] -= n
                balances[b] += n
                history.append(("transfer", a, b, n))
                ok = True
        elif v == "freeze" and len(t) == 2:
            a = t[1]
            if a in balances and a not in frozen:
                frozen.add(a)
                history.append(("freeze", a))
                ok = True
        elif v == "unfreeze" and len(t) == 2:
            a = t[1]
            if a in balances and a in frozen:
                frozen.remove(a)
                history.append(("unfreeze", a))
                ok = True
        elif v == "undo" and len(t) == 1 and history:
            rec = history.pop()
            kind = rec[0]
            if kind == "open":
                del balances[rec[1]]
                frozen.discard(rec[1])
            elif kind == "deposit":
                balances[rec[1]] -= rec[2]
            elif kind == "withdraw":
                balances[rec[1]] += rec[2]
            elif kind == "transfer":
                balances[rec[1]] += rec[3]
                balances[rec[2]] -= rec[3]
            elif kind == "freeze":
                frozen.remove(rec[1])
            else:
                frozen.add(rec[1])
            ok = True
        if not ok:
            rejected.append(i)
    return balances, rejected
